/**
 * The Blueprint
 * -------------
 * The ark is to be three hundred cubits long, fifty wide, and thirty high, with a roof, a door, and three decks. Stage: a man marking out the great hull with a line and a cubit rod, the shape of the ark in the dust; the light of a late afternoon on a plan of wood.
 *
 * Palette 0x2a1e0c → 0x150e06 · light: dusk · hero: ark
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./noah-kit.js.
 */

import { THREE, createScene, house, oak, ark, person, birds } from './noah-kit.js';

const BG = 0x2a1e0c;
const GROUND = 0x080502;

export function build(group) {
    const W = createScene(group, { seed: 2991602030, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x080502, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 12, 0, -19, 1.0 + W.r() * 0.3, { mud: 0x140d06 });
    house(W, group, -19, 0, -9, 0.8 + W.r() * 0.3, { mud: 0x150e06 });

    /* trees: broadleaf shade */
    oak(W, group, -7.0, 0, -56.8, 1.10, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 65.9, 0, -30.3, 0.93, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 61.4, 0, -6.3, 1.37, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* hero: the ark riding the flood */
    ark(W, group, 0, 0.2, 0, 1.0, { ry: 0.25 });

    /* hero: the ark */
    ark(W, group, 0, 0.2, 0, 1.1, { ry: 0.2 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2a1e0c, ry: -0.60, s: 1.10 });
    person(W, group, [4.5, 0, 6], { robe: 0x150e06, ry: -0.09, s: 1.18 });
    person(W, group, [1, 0, -5], { robe: 0x080502, ry: -0.62, s: 1.11 });

    /* birds: slow circles high above */
    birds(W, group, 6, 55, { y: 26 });

    return W.finish();
}

export default { build };
